    // Find the bottom-most point (or leftmost in case of tie)
    Point2d start = points[0];
    for (const Point2d& p : points) {
        if (p.y() < start.y() || (p.y() == start.y() && p.x() < start.x())) {
            start = p;
        }
    }

    // Sort points by polar angle with respect to the starting point
    std::vector<Point2d> sortedPoints = points;
    std::sort(sortedPoints.begin(), sortedPoints.end(), [&](const Point2d& a, const Point2d& b) {
        // Cross product to determine the orientation
        double cross = (a.x() - start.x()) * (b.y() - start.y()) - (a.y() - start.y()) * (b.x() - start.x());
        if (cross == 0) {
            // Collinear points: sort by distance from start
            double distA = (a.x() - start.x()) * (a.x() - start.x()) + (a.y() - start.y()) * (a.y() - start.y());
            double distB = (b.x() - start.x()) * (b.x() - start.x()) + (b.y() - start.y()) * (b.y() - start.y());
            return distA < distB;
        }
        return cross > 0;
    });

    // Remove duplicates
    sortedPoints.erase(std::unique(sortedPoints.begin(), sortedPoints.end()), sortedPoints.end());

    if (sortedPoints.size() < 3) {
        return sortedPoints;
    }

    // Graham scan algorithm
    std::vector<Point2d> hull;
    hull.push_back(sortedPoints[0]);
    hull.push_back(sortedPoints[1]);

    for (size_t i = 2; i < sortedPoints.size(); i++) {
        // Remove last point from hull if turning clockwise
        while (hull.size() > 1) {
            Point2d p2 = hull.back();
            hull.pop_back();
            Point2d p1 = hull.back();

            // Cross product to check orientation
            double cross = (sortedPoints[i].x() - p1.x()) * (p2.y() - p1.y()) - 
                         (p2.x() - p1.x()) * (sortedPoints[i].y() - p1.y());

            if (cross > 0) {  // Counter-clockwise turn
                hull.push_back(p2);
                break;
            }
        }
        hull.push_back(sortedPoints[i]);
    }

    return hull;
